import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'

export default function CardSmallExample() {
  return (
    <Card size="sm" class="w-full max-w-sm">
      <CardHeader><CardTitle>Small Card</CardTitle><CardDescription>This card uses the small size variant.</CardDescription></CardHeader>
      <CardContent><p>The card component supports a size prop that can be set to &quot;sm&quot; for a more compact appearance.</p></CardContent>
      <CardFooter><Button variant="outline" size="sm" class="w-full">Action</Button></CardFooter>
    </Card>
  )
}
